past_records = [("mard", True), ("mard", True), ("mard", False), ("mard", True),
                ("aurat", False), ("aurat", True), ("aurat", False), ("aurat", False)]

for group in ["mard", "aurat"]:
    total = 0
    selected = 0
    for person, chosen in past_records:
        if person == group:
            total += 1
            if chosen:
                selected += 1
    rate = selected / total * 100
    print(f"{group}: {total} mein se {selected} chune gaye ({rate:.0f}%)")

print("Is data se seekhne wala AI bhi isi farq ko dohraye ga.")
